create table if not exists public.soccer_grid_puzzles (
  id         uuid        primary key default gen_random_uuid(),
  puzzle_id  text        not null unique,
  rows_json  jsonb       not null,
  cols_json  jsonb       not null,
  sort_order smallint    not null,
  created_at timestamptz not null default now()
);
alter table public.soccer_grid_puzzles enable row level security;
do $$ begin
  if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'soccer_grid_puzzles' and policyname = 'Public read-only') then
    create policy "Public read-only" on public.soccer_grid_puzzles for select to anon, authenticated using (true);
  end if;
end $$;
on conflict (puzzle_id) do update set
  rows_json = excluded.rows_json, cols_json = excluded.cols_json, sort_order = excluded.sort_order;
